<?php
namespace App\Http\Controllers;
use App\Models\{EggProduct,InventoryTransaction,ProductionRecord}; use App\Services\InventoryService; use Illuminate\Http\Request;
class ReportController { public function index(Request $r,InventoryService $i){$from=$r->input('from',now()->startOfMonth()->toDateString());$to=$r->input('to',now()->toDateString());$type=$r->input('type','production');$pid=$r->input('product_id');$products=EggProduct::where('status','active')->orderBy('product_name')->get();$pq=ProductionRecord::with('product')->whereBetween('production_date',[$from,$to]);if($pid)$pq->where('product_id',$pid);$tq=InventoryTransaction::with('product','recorder')->whereBetween('transaction_date',[$from,$to]);if($pid)$tq->where('product_id',$pid);$productions=$pq->latest('production_date')->get();$transactions=$tq->latest('transaction_date')->get();return view('admin.reports.index',['from'=>$from,'to'=>$to,'type'=>$type,'productId'=>$pid,'products'=>$products,'productions'=>$productions,'transactions'=>$transactions,'totalProduction'=>$productions->sum('quantity_produced'),'saleableEggs'=>$productions->sum('saleable_quantity'),'damagedEggs'=>$productions->sum('damaged_quantity'),'rejectedEggs'=>$productions->sum('rejected_quantity'),'currentInventory'=>$i->allBalances()->sum('current_stock')]);} }
